// Input 0: all scraped+normalized jobs
// Input 1: existing jobs from Google Sheets (read above, passed via Set node)
// We join them in workflow: existing URLs come from context set before this node
const allItems = $input.all();

// Separate source note items and real jobs
const jobs = allItems.filter(i => i.json.job_url && i.json.job_title);

// Read existing URLs from the previous execution's static data (set via workflow vars)
// In practice, connect the Google Sheets read output to a Set node that stores URLs in $vars
// then read them here via $vars.existingUrls
const existingUrlsRaw = $vars.existingJobUrls || '[]';
let existingUrls = new Set();
try { existingUrls = new Set(JSON.parse(existingUrlsRaw)); } catch(e) {}

const seen = new Set();
const newJobs = [];
const today = new Date().toISOString().split('T')[0];

for (const item of jobs) {
  const j = item.json;
  const url = (j.job_url || '').trim();
  const dedupKey = url || (j.company + '|' + j.job_title).toLowerCase();
  if (!url) continue;
  if (existingUrls.has(url)) continue;
  if (seen.has(dedupKey)) continue;
  seen.add(dedupKey);
  newJobs.push({ json: { ...j, date_found: today } });
}

if (newJobs.length === 0) {
  return [{ json: { _info: 'No new jobs found today', count: 0 } }];
