const items = $input.all();

// Reject patterns (case-insensitive)
const rejectPatterns = [
  /\bus( |-)only\b/i,
  /\bunited states only\b/i,
  /\bcanada only\b/i,
  /\buk only\b/i,
  /\beurope only\b/i,
  /\beu only\b/i,
  /\baustralia only\b/i,
  /\bmust be based in\b/i,
  /\bmust live in\b/i,
  /\bmust reside in\b/i,
  /\bmust be located in\b/i,
  /\bmust be authorized to work in\b/i,
  /\blocal work permit required\b/i,
  /\brequires.*work.*authorization\b/i,
  /\bonsite\b/i,
  /\bon-site\b/i,
  /\bhybrid\b/i,
  /\boffice required\b/i,
  /\bremote within\b.*\b(us|uk|eu|canada|australia)\b/i,
  /\bin-office\b/i,
  /\bfixed.*us.*hours\b/i,
  /\bfixed.*eu.*hours\b/i,
  /\best.*9.*(am|to).*5\b/i,
  /\bpst.*9.*(am|to).*5\b/i,
  /\bauthorized to work in the (us|uk|eu|canada|australia)\b/i,
  /\beligible to work in the (us|uk|eu|canada|australia)\b/i
];

// Location text reject (when location field explicitly names restricted countries)
const locationRejectPatterns = [
  /^(usa|us|united states|canada|uk|united kingdom|eu|europe|australia)$/i,
  /\bonly\b.*\b(us|uk|eu|canada|australia)\b/i
];

const kept = [];
const rejected = [];

for (const item of items) {
  // Skip info-only items
  if (item.json._info || !item.json.job_title) continue;

  const text = ((item.json.description || '') + ' ' + (item.json.location_text || '') + ' ' + (item.json.tags || '')).toLowerCase();
  const loc = (item.json.location_text || '').toLowerCase().trim();

  let rejectReason = null;

  for (const pattern of rejectPatterns) {
    if (pattern.test(text)) {
      rejectReason = 'Hard reject: ' + pattern.toString();
      break;
    }
  }

  if (!rejectReason) {
    for (const pattern of locationRejectPatterns) {
      if (pattern.test(loc)) {
        rejectReason = 'Location restricted: ' + loc;
        break;
      }
    }
  }

  if (rejectReason) {
    rejected.push({ json: { ...item.json, reject_reason: rejectReason, reject_stage: 'hard_filter' } });
  } else {
    kept.push({ json: item.json });
  }
}

return [kept, rejected];

