const j = $input.item.json;

// ── Parse AI response ──────────────────────────────────────────
let aiResult = {};
try {
  const raw = j.choices?.[0]?.message?.content || '{}';
  aiResult = JSON.parse(raw);
} catch(e) {
  aiResult = { taiwan_eligible: 'unclear', reason: 'parse error', location_risk: 'medium', timezone_risk: 'medium', contractor_possible: 'unclear', decision: 'manual_check' };
}

// We need the original job fields — they were passed via the pairedItem mechanism.
// In n8n, when the HTTP Request runs per-item, the input item's JSON contains the job data.
// The response is in choices[0].message.content. The original job fields are accessible
// from the HTTP Request node's input pairedItem.
const origJob = $('AI: Taiwan Eligibility Check').item.json._originalJob || {};

// ── Async signals ──────────────────────────────────────────────
const desc = ((origJob.description || j._description || '') + ' ' + (origJob.tags || j._tags || '')).toLowerCase();

const asyncSignals = [
  /\basync(hronous)?\b/i,
  /\bflexible hours?\b/i,
  /\bflexible schedule\b/i,
  /\bdistributed team\b/i,
  /\bremote.?first\b/i,
  /\blow.?meeting\b/i,
  /\bwork across time.?zones\b/i,
  /\bno.?overlap\b/i
];
const rejectAsyncSignals = [
  /\bstrict 9.?to.?5\b/i,
  /\bfixed (est|pst|cet|cst) hours\b/i,
  /\bdaily live calls required\b/i,
  /\bmust overlap full business day\b/i
];

let asyncScore = 0;
let asyncLevel = 'low';
for (const p of rejectAsyncSignals) {
  if (p.test(desc)) { asyncLevel = 'rejected'; break; }
}
if (asyncLevel !== 'rejected') {
  for (const p of asyncSignals) {
    if (p.test(desc)) asyncScore++;
  }
  if (asyncScore >= 3) asyncLevel = 'high';
  else if (asyncScore >= 1) asyncLevel = 'medium';
  else asyncLevel = 'low';
}

// ── Role fit ───────────────────────────────────────────────────
const title = (origJob.job_title || j._job_title || '').toLowerCase();
const rolePatterns = [
  [/data (analyst|scientist|engineer)/i, 25, 'data'],
  [/business intelligence|bi analyst/i, 25, 'bi'],
  [/marketing analyst|growth analyst|performance marketing/i, 25, 'marketing_analytics'],
  [/ai (marketing|automation|workflow|specialist)/i, 25, 'ai_marketing'],
  [/martech|mar.?tech/i, 25, 'martech'],
  [/automation specialist/i, 25, 'automation'],
  [/junior data scientist/i, 25, 'data'],
  [/creative strateg/i, 15, 'creative_strategy'],
  [/product analyst/i, 15, 'product'],
  [/seo|ppc|sem|paid (search|social)|ads manager/i, 15, 'performance_mktg'],
  [/analyst|data/i, 15, 'analyst_general']
];
let rolePoints = 0;
let roleCategory = 'other';
for (const [pattern, pts, cat] of rolePatterns) {
  if (pattern.test(title) || pattern.test(desc)) {
    if (pts > rolePoints) { rolePoints = pts; roleCategory = cat; }
  }
}

// ── Taiwan eligibility score ───────────────────────────────────
let taiwanPoints = 0;
const eligibility = aiResult.taiwan_eligible || 'unclear';
const locRisk = aiResult.location_risk || 'medium';
if (eligibility === 'yes' && locRisk === 'low') taiwanPoints = 40;
else if (eligibility === 'yes') taiwanPoints = 30;
else if (eligibility === 'unclear') taiwanPoints = 20;
else taiwanPoints = 0;

// Check for APAC friendly in description
if (/\bapac\b/i.test(desc) && taiwanPoints < 30) taiwanPoints = 30;

// ── Async score points ─────────────────────────────────────────
let asyncPoints = 0;
if (asyncLevel === 'high') asyncPoints = 25;
else if (asyncLevel === 'medium') asyncPoints = 20;
else if (asyncLevel === 'low') asyncPoints = 10;

// ── Salary score ───────────────────────────────────────────────
const salaryStr = (origJob.salary || j._salary || '').replace(/,/g, '');
const salaryNums = salaryStr.match(/\d+/g);
let salaryPoints = 0;
let salaryNote = salaryStr || 'not listed';
if (salaryNums) {
  const highest = Math.max(...salaryNums.map(Number));
  if (highest >= 5000) salaryPoints = 25;
  else if (highest >= 3000) salaryPoints = 15;
  else salaryPoints = 10;
}

// ── Total score ────────────────────────────────────────────────
const totalScore = taiwanPoints + asyncPoints + rolePoints + salaryPoints;

// ── Why good fit (brief) ───────────────────────────────────────
const reasons = [];
if (eligibility === 'yes') reasons.push('Taiwan eligible');
if (asyncLevel === 'high') reasons.push('async-first');
if (roleCategory !== 'other') reasons.push(roleCategory + ' role');
if (salaryPoints >= 15) reasons.push('good salary');
const whyGoodFit = reasons.join(', ') || 'needs manual review';

// ── Final decision ─────────────────────────────────────────────
let decision = 'reject';
if (aiResult.decision === 'reject' || eligibility === 'no' || locRisk === 'high') {
  decision = 'reject';
} else if (totalScore >= 85 && eligibility !== 'no') {
  decision = 'apply';
} else if (totalScore >= 70 && eligibility !== 'no') {
  decision = 'keep';
} else if (aiResult.decision === 'manual_check' || eligibility === 'unclear') {
  decision = 'manual_check';
}

return {
  json: {
    // Preserve original job fields
    date_found: origJob.date_found || j.date_found || new Date().toISOString().split('T')[0],
    job_id: origJob.job_id || j.job_id || '',
    job_title: origJob.job_title || j.job_title || j._job_title || '',
    company: origJob.company || j.company || j._company || '',
    job_url: origJob.job_url || j.job_url || j._job_url || '',
    source: origJob.source || j.source || '',
    location_text: origJob.location_text || j.location_text || '',
    salary: origJob.salary || j.salary || '',
    description: origJob.description || j.description || '',
    posted_date: origJob.posted_date || j.posted_date || '',
    tags: origJob.tags || j.tags || '',
    // AI results
    taiwan_eligible: eligibility,
    taiwan_reason: aiResult.reason || '',
    location_risk: locRisk,
    timezone_risk: aiResult.timezone_risk || 'medium',
    contractor_possible: aiResult.contractor_possible || 'unclear',
    // Processing results
    async_level: asyncLevel,
    role_category: roleCategory,
    score: totalScore,
    taiwan_points: taiwanPoints,
    async_points: asyncPoints,
    role_points: rolePoints,
    salary_points: salaryPoints,
    why_good_fit: whyGoodFit,
    decision: decision,
    application_status: 'new',
    notes: ''
  }
};

// "I can do this job while living in Taiwan, without moving,
//  without foreign work authorization, and without destroying my sleep schedule."
const items = $input.all();
const kept = [];
const rejected = [];

for (const item of items) {
  const j = item.json;
  const canWorkFromTaiwan = j.taiwan_eligible !== 'no' && j.location_risk !== 'high';
  const noForeignAuth = j.taiwan_eligible !== 'no';
  const noSleepDestruction = j.timezone_risk !== 'high' && j.async_level !== 'rejected';
  const passesRule = canWorkFromTaiwan && noForeignAuth && noSleepDestruction;
  const meetsScoreThreshold = j.score >= 70;

  if (!passesRule || !meetsScoreThreshold) {
    rejected.push({
      json: {
        date_rejected: j.date_found,
        job_title: j.job_title,
        company: j.company,
        job_url: j.job_url,
        reason: !passesRule
          ? `Failed one-sentence rule: taiwan=${j.taiwan_eligible}, loc_risk=${j.location_risk}, tz_risk=${j.timezone_risk}, async=${j.async_level}`
          : `Score too low: ${j.score}/100`
      }
    });
  } else {
    kept.push({ json: j });
  }
}

// Output 0: kept jobs (70+, pass one-sentence rule)
// Output 1: rejected jobs
return [kept, rejected];

