const items = $input.all();

if (items.length === 0 || (items.length === 1 && items[0].json._info)) {
  return [{ json: { subject: 'Daily Taiwan Async Jobs — No New Jobs Today', body: 'No new eligible jobs found today. All sources returned duplicates or failed the Taiwan eligibility filter.' } }];
}

// Sort by score descending
const jobs = items
  .filter(i => i.json.job_title && i.json.score)
  .sort((a, b) => (b.json.score || 0) - (a.json.score || 0));

const today = new Date().toLocaleDateString('en-US', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric', timeZone: 'Asia/Taipei' });

// Top jobs list
const topJobs = jobs.filter(i => i.json.score >= 70);
const manualCheckJobs = jobs.filter(i => i.json.taiwan_eligible === 'unclear' && i.json.score >= 70);

// Count rejections by reason (from static data stored earlier if available)
let rejectedCount = { us_only: 0, eu_only: 0, hybrid: 0, timezone: 0 };

let digestText = `DAILY TAIWAN ELIGIBLE ASYNC REMOTE JOBS\n${today}\n`;
digestText += `${'═'.repeat(50)}\n\n`;
digestText += `FOUND ${topJobs.length} ELIGIBLE JOB(S) TODAY\n\n`;

if (topJobs.length === 0) {
  digestText += 'No jobs cleared all filters today. Check manual_check section.\n';
} else {
  digestText += `TOP JOBS TODAY:\n${'─'.repeat(40)}\n\n`;
  topJobs.slice(0, 10).forEach((item, idx) => {
    const j = item.json;
    const scoreEmoji = j.score >= 85 ? '🔥' : j.score >= 75 ? '⭐' : '✅';
    digestText += `${idx + 1}. ${j.job_title}\n`;
    digestText += `   Company: ${j.company}\n`;
    digestText += `   Score: ${scoreEmoji} ${j.score}/100\n`;
    digestText += `   Taiwan eligible: ${j.taiwan_eligible}\n`;
    digestText += `   Reason: ${j.taiwan_reason}\n`;
    digestText += `   Async level: ${j.async_level}\n`;
    digestText += `   Timezone risk: ${j.timezone_risk}\n`;
    digestText += `   Salary: ${j.salary || 'Not listed'}\n`;
    digestText += `   Why it fits Jerry: ${j.why_good_fit}\n`;
    digestText += `   Apply link: ${j.job_url}\n`;
    if (j.cover_letter) {
      digestText += `\n   --- COVER LETTER DRAFT ---\n${j.cover_letter}\n   --- END COVER LETTER ---\n`;
    }
    digestText += '\n';
  });
}

if (manualCheckJobs.length > 0) {
  digestText += `\nMANUAL CHECK REQUIRED (${manualCheckJobs.length} jobs):\n${'─'.repeat(40)}\n`;
  manualCheckJobs.forEach((item, idx) => {
    const j = item.json;
    digestText += `${idx + 1}. ${j.job_title} @ ${j.company} — Score: ${j.score} — ${j.job_url}\n`;
    digestText += `   Reason unclear: ${j.taiwan_reason}\n\n`;
  });
}

digestText += `\nREJECTED TODAY:\n${'─'.repeat(40)}\n`;
